CREATE TABLE work_orders(id UUID PRIMARY KEY,repair_request_id UUID NOT NULL UNIQUE,client_id UUID NOT NULL,employee_id UUID NOT NULL,diagnosis VARCHAR(2000) NOT NULL,status VARCHAR(32) NOT NULL,total_amount DECIMAL(12,2) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE work_order_services(id UUID PRIMARY KEY,work_order_id UUID NOT NULL REFERENCES work_orders(id),service_id UUID NOT NULL,service_name VARCHAR(150) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),line_total DECIMAL(12,2) NOT NULL);
CREATE TABLE work_order_parts(id UUID PRIMARY KEY,work_order_id UUID NOT NULL REFERENCES work_orders(id),part_id UUID NOT NULL,part_name VARCHAR(150) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),line_total DECIMAL(12,2) NOT NULL,reservation_key VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE work_order_status_history(id UUID PRIMARY KEY,work_order_id UUID NOT NULL REFERENCES work_orders(id),previous_status VARCHAR(32),new_status VARCHAR(32) NOT NULL,changed_by UUID NOT NULL,changed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_work_client ON work_orders(client_id); CREATE INDEX idx_work_status ON work_orders(status);
CREATE TABLE outbox_events(event_id UUID PRIMARY KEY,topic VARCHAR(120) NOT NULL,aggregate_id UUID NOT NULL,event_type VARCHAR(100) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published BOOLEAN NOT NULL,published_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL);
